//! Raven's data model and sync protocol.
//!
//! The server uses these types directly. The clients get them as TypeScript,
//! generated by `bun run gen:types` into `packages/types`.
//!
//! Only settings sync: the apps a workspace watches and its members. What
//! Raven hears from the apps (calls, logs, checks) stays on the server and
//! is read live.
//!
//! On the wire, field names are snake_case, the same as the database columns.

mod account;
mod app;
mod model;
mod protocol;
mod user;

pub use account::{
    Me, MemberInfo, Role, UpdateAccessRequest, UpdateMemberRequest, UpdateProfileRequest,
    UpdateWorkspaceRequest, UserInfo, WorkspaceInfo, clean_name, normalize_email, url_key_from,
};
pub use app::{App, AppCreate, AppKey, AppPatch};
pub use model::{Actor, ModelKind, Validate, ValidationError, Write};
pub use protocol::{
    ApiError, Bootstrap, Operation, ServerMessage, SyncAction, SyncEntry, Transaction,
    TransactionResult,
};
pub use user::User;
